RpcClient Client(string mode,TimeSpan? timeout=null){var dir=Path.Combine(root,"rpc-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);var executable=Path.Combine(Path.GetFullPath(Path.Combine(System.Runtime.InteropServices.RuntimeEnvironment.GetRuntimeDirectory(),"..","..","..")),OperatingSystem.IsWindows()?"dotnet.exe":"dotnet");List<string> argv=[Assembly.GetExecutingAssembly().Location];argv.AddRange(["--rpc-fixture",mode]);var env=ChildEnvironment.Create(Environment.GetEnvironmentVariables().Cast<System.Collections.DictionaryEntry>().ToDictionary(x=>(string)x.Key,x=>(string)x.Value!),dir);var info=ChildEnvironment.StartInfo(executable,argv,env,dir);return new(new StdioTransport(info),timeout);}
