static async Task Fixture(string mode){int identities=0;while(await Console.In.ReadLineAsync() is string line){var data=JsonDocument.Parse(line).RootElement;var method=data.GetProperty("method").GetString();if(!data.TryGetProperty("id",out var id))continue;object? result=new{};
    if(method=="account/read"){identities++;result=new{account=mode=="unauthed"?null:new{type="chatgpt",email=mode=="change"&&identities>1?"changed@example.test":"fixture@example.test",planType="plus"}};}
    if(method=="account/rateLimits/read"){if(mode=="timeout")continue;if(mode=="exit")return;if(mode=="error"){Console.WriteLine(JsonSerializer.Serialize(new{id=id.GetInt32(),error=new{code=-32001,message="private-detail-do-not-display"}}));continue;}result=new{rateLimits=new{primary=new{usedPercent=23,windowDurationMins=300,resetsAt=2000000000}}};}
    if(method=="account/login/start"){Console.WriteLine(JsonSerializer.Serialize(new{method="account/login/completed",@params=new{loginId="fixture",success=true}}));result=new{loginId="fixture",authUrl="https://auth.openai.com/fixture"};}
    var output=JsonSerializer.Serialize(new{id=id.GetInt32(),result});if(mode=="fragmented"){for(var i=0;i<output.Length;i+=7){Console.Write(output.Substring(i,Math.Min(7,output.Length-i)));await Console.Out.FlushAsync();await Task.Delay(1);}Console.WriteLine();}else Console.WriteLine(output);
}}

static async Task ProviderFixture(string[] args){
    File.AppendAllText("provider-fixture-trace.txt",string.Join(" ",args)+Environment.NewLine);
    var config=Environment.GetEnvironmentVariable("CLAUDE_CONFIG_DIR");
    if(args.SequenceEqual(new[]{"--version"})){Console.WriteLine(config==null?"1.4.9":"2.1.295 (Claude Code)");return;}
    if(args.SequenceEqual(new[]{"auth","status"})){Console.WriteLine(JsonSerializer.Serialize(new{loggedIn=true,authMethod="claude.ai",email="fixture@example.test",configDirectory=config}));return;}
    if(config==null){if(!args.SequenceEqual(ProviderQuota.AntigravityArguments))throw new Exception("Unsafe Antigravity command");Console.WriteLine("""{"num_turns":0,"usage":{"total_tokens":0},"command":{"name":"usage","data":{"groups":[{"buckets":[{"id":"fixture-pro","name":"Fixture Pro","remaining_fraction":0.75}]}]}}}""");return;}
    if(!args.SequenceEqual(ProviderQuota.ClaudeArguments))throw new Exception("Unsafe Claude command");
    bool initialized=false;while(await Console.In.ReadLineAsync() is {} line){using var doc=JsonDocument.Parse(line);var x=doc.RootElement;var req=x.GetProperty("request");var subtype=req.GetProperty("subtype").GetString();if(x.GetProperty("type").GetString()!="control_request")throw new Exception("Model prompts forbidden");object value;
        if(subtype=="initialize"){initialized=true;value=new{};}else{if(!initialized||subtype!="get_usage"||!req.GetProperty("skip_behaviors").GetBoolean())throw new Exception("Transcript access forbidden");value=new{rate_limits_available=true,rate_limits=new{five_hour=new{utilization=100}}};}
        Console.WriteLine(JsonSerializer.Serialize(new{type="control_response",response=new{subtype="success",request_id=x.GetProperty("request_id").GetString(),response=value}}));await Console.Out.FlushAsync();
    }
}
